interface Order { id: string; total: number }
function applyDiscount(order: Order, percent: number) {
  order.total = order.total - order.total * percent;
}
const o: Order = { id: "A1", total: 100 };
applyDiscount(o, 0.1);
console.log(o.total);

interface User { id: string; name: string }
// Version A: in-place update
function updateUserV1(user: User, name: string) {
  user.name = name;
  return user;
}

// Version B: return new object
function updateUserV2(user: User, name: string) {
  return { ...user, name };
}
